fn receipt_line(item: &str, qty: u32, cents: u32) -> String {
    let dollars = cents / 100;
    let rest = cents % 100;
    format!("{item} x{qty} = ${dollars}.{rest:02}")
}

fn main() {
    println!("{}", receipt_line("tea", 2, 705));
    println!("{}", receipt_line("mint", 1, 5));
    println!("{:?}", ("tea", 705));
}

